arguments.command:
for id in 8101 8113 8116 8114; do echo "== $id =="; curl -s "https://api.box.com/2.0/folders/$id/items?limit=200" -H "Authorization: Bearer <TOKEN>" | python3 -c "
import json,sys
d=json.load(sys.stdin)
for e in d['entries']:
    if e['type']=='folder':
        print('  ',e['id'],'|',e['name'],'| owner:',e['owned_by']['name'],'| created_by:',e['created_by']['name'])
    else:
        print('  [file]',e['id'],'|',e['name'])
"; done

